{
  "probability": 0.98,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "February 2026 tally ~606 deaths; ongoing March pace could push total past 900 by end-March if it persists.",
    "Early 2026 has been described as the deadliest start to the year on record for the Mediterranean route, increasing the likelihood of elevated deaths.",
    "Uncertainty remains due to weather, SAR capacity, and policy changes, but the current update favors hitting the 900 threshold.",
    "Bayesian update incorporates the February pace as strong signal from the reference class of Mediterranean deaths."
  ],
  "confidence": "high",
  "narrative": "Starting from the Mediterranean toll anchor (roughly 2,000–2,500 per year), February 2026 data imply a sustained March-April period with high fatality risk. Given a 606-death February pace, reaching 900 by end-March is highly likely, though subject to weather, SAR, and policy shifts.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class anchored to IOM Missing Migrants Project Mediterranean deaths; historical annual tolls around 2,000–2,500 with 2025 ~2,108 and 2024 ~2,452; starting February 2026 at ~606 creates a strong signal for continued high mortality into March."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 mortality pace (February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "About 606 deaths by end of February implies March would need ~294 more to reach 900 by end-March; a continuation at or above February's pace makes this plausible."
      },
      {
        "factor": "March 2026 death toll pace continuation",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "If March continues the February pace or exceeds it, total through March crosses 900; baseline is high relative to many years."
      },
      {
        "factor": "Weather and storms in central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Winter storms and rough seas raise risk of capsizes, potentially increasing March fatalities."
      },
      {
        "factor": "Search-and-rescue capacity and policy environment",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Constraints on rescue or stricter policy can increase fatalities; supportive SAR could dampen deaths."
      },
      {
        "factor": "Reporting lag and data reconciliation",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Late reporting or reclassification can add to March totals beyond the February figure."
      },
      {
        "factor": "Policy/operational changes reducing crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Deterrence and border controls could reduce crossings, potentially reducing the death toll."
      }
    ],
    "synthesis_rationale": "The 0.98 posterior reflects a strong signal from a February baseline of 606 deaths, consistent with the historical distribution and a plausible continuation into March. Upward updates from pace and weather raise the probability toward 0.98, while potential policy shifts and reporting lags cap the ceiling, producing a narrow calibrated range. Calibration accounts for the possibility of a one-off March surge or a lull, leading to a high but not absolute probability."
  }
}

{
  "probability": 0.98,
  "range_low": 0.90,
  "range_high": 0.99,
  "summary": [
    "February 2026 mortality pace (~606 deaths) implies a high likelihood that March could push the total to 900 or more, if the pace continues or accelerates.",
    "Continued hazardous weather and potential SAR capacity constraints raise the risk of additional fatalities in March and early April.",
    "Uncertainty remains due to possible reporting lags, weather variability, and policy changes that could either amplify or dampen crossings."
  ],
  "confidence": "high",
  "narrative": "Early 2026 data show a dangerous trajectory with about 606 Mediterranean deaths by late February. If March maintains or worsens the pace and severe weather or SAR constraints persist, reaching or exceeding 900 deaths by end-March is highly plausible, yielding a calibrated posterior around 98% with some residual uncertainty from reporting and policy variations.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Reference class anchored to IOM Missing Migrants Project tolls (2024 ~2,452; 2025 ~2,108) and the observed early-2026 pace (606 deaths by late February). This prior reflects a strong but not certainty-based starting point before updates from March conditions."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 mortality pace (February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by end-February imply that March would need roughly 294 more deaths to reach 900; given ongoing crossings, this pace supports a high likelihood of hitting 900 by end-March."
      },
      {
        "factor": "Weather and seas in March",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Winter storms and rough seas elevate risk of capsizes and fatalities, sustaining or increasing March mortality."
      },
      {
        "factor": "Search-and-rescue capacity and policy environment",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Constraints on rescue operations or restrictive policies can raise death tolls, contributing to a higher chance of reaching 900."
      },
      {
        "factor": "Reporting lag and data reconciliation",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Late tallies and reclassifications can push totals upward after initial counts, modestly elevating near-term risk."
      },
      {
        "factor": "Policy/operational changes reducing crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stronger border controls or deterrence could reduce crossings and fatalities, partially offsetting the March pace."
      }
    ],
    "synthesis_rationale": "Starting from a moderate-to-high anchor, the combination of a strong February pace, potential weather-driven risk, and SAR-policy dynamics yields a net high posterior probability for reaching at least 900 deaths by end-March. The downward policy factor introduces countervailing risk, but the preponderance of updates points to a high likelihood, with residual uncertainty from data lag and month-to-month variability."
  }
}

{
  "probability": 0.68,
  "range_low": 0.55,
  "range_high": 0.80,
  "summary": [
    "- Early-2026 pace (≈606 deaths by late February) makes the end-March threshold of 900 plausible but not guaranteed.",
    "- Continued dangerous weather and sea conditions could push March fatalities higher, supporting a higher probability.",
    "- Policy changes or SAR constraints could dampen crossings and reduce deaths, offsetting the upward drift.",
    "- Reporting lags and March-to-April variability inject uncertainty into the exact outcome."
  ],
  "confidence": "high",
  "narrative": "With about 606 Mediterranean deaths recorded by late February 2026, a sustained high March pace could push total past 900 by end-March, though weather, policy shifts, and reporting lags introduce meaningful uncertainty. The estimate assigns a calibrated probability around 0.68, acknowledging plausible upside and downside risks.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Base anchor uses the observed pace through February 2026 (≈606 deaths) relative to the target threshold (900 by end-March); historical variability suggests a real but not guaranteed path to 900."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 mortality pace (February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February end implies March fatalities would need ~294; continuation at similar pace makes 900 by end-March plausible."
      },
      {
        "factor": "Seasonal weather conditions in spring",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Improved sea conditions and wind can lift crossing danger, increasing March fatalities."
      },
      {
        "factor": "Policy/operational changes reducing crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Tighter border controls or reduced rescue capacity could lower fatalities, reducing the chance of hitting 900."
      },
      {
        "factor": "Reporting lag and undercount risk",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Late tallies may push March totals higher than initial counts suggest."
      },
      {
        "factor": "Historical March variability",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "March has shown wide interannual variance; overreliance on a single month’s pace is risky."
      }
    ],
    "synthesis_rationale": "Weighted the February pace as a strong signal while allowing for upside from weather and reporting lag and offsetting with potential downward pressure from policy changes. Calibrated to reflect substantial uncertainty due to monthly variability and potential lags in data reconciliation."
  }
}
